# ==============================================================================
# BO CAI DAT PHICOMM R1 CHO WINDOWS (POWERSHELL)
# Source code: https://github.com/vdt34/vdt34.github.io/blob/main/r1/install_src.ps1
# Tu dong cau hinh WiFi, quet tim loa trong LAN, giao dien Tieng Viet UTF-8
# ==============================================================================
param()
try { chcp 65001 >$null } catch {}
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { $OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}

$R1_B64 = @"

"@

$R1_CODE = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($R1_B64)).TrimStart([char]0xFEFF)
$R1_SB = [ScriptBlock]::Create($R1_CODE)
if ($args -and $args.Count -gt 0) {
    & $R1_SB @args
} else {
    & $R1_SB
}
